 return dict(id=f'{sub}-i{i:02}',kcs=[k],kind='short',difficulty=d,command_word=word,source={'type':'generated'},stem=stem,marks=len(points),rubric=[{'point':p,'keywords':[[w] for w in keys]} for p,keys in points],explanation=explain,hints=['Recall the relevant Group 17 trend or observation.','Separate the reagent from the product.','Start with the halide ion involved.'])
